def prepare_directory(root, generation):
    # A caller-supplied root alias denotes its real directory. Child aliases are never followed.
    root = Path(root).resolve()
    root.mkdir(parents=True, exist_ok=True)
    directory = root / generation
    if directory.is_symlink():
        raise ValueError('generation symlink is not allowed')
    directory.mkdir(exist_ok=True)
    if directory.resolve() != directory:
        raise ValueError('generation escapes root')
    for name in ARTIFACT_NAMES:
        if (directory / name).is_symlink():
            raise ValueError('artifact symlink is not allowed')
    return directory


def valid_generation(value):
    if not isinstance(value,str) or not re.fullmatch(r'[a-z0-9_-]{1,32}',value):
        raise ValueError('invalid generation')
    return value


def ranked(command,key):
    raw=command('ZREVRANGE',key,0,-1,'WITHSCORES')
    if len(raw)>20000:
        raise ValueError('season budget exceeded')
    result=[]
    for member,score in zip(raw[::2],raw[1::2]):
        value=float(score)
        if not math.isfinite(value) or not value.is_integer() or abs(value)>2**53-1:
            raise ValueError('integer score budget')
        result.append({'member':member,'score':int(value)})
    return result


def expectation(plan):
    rows=plan['source_rows']
    if plan['operation']=='correct':
        values={r['member']:r['score']for r in rows}
        values[plan['correction']['member']]=plan['correction']['score']
        rows=[{'member':member,'score':score}for member,score in sorted(
            values.items(),key=lambda pair:(pair[1],pair[0].encode()),reverse=True)]
    return rows


def changes_for(plan,rows):
    before={r['member']:r['score']for r in plan['source_rows']}
    changes=[]
    if plan['operation']=='correct':
        for row in rows:
            if before.get(row['member'])!=row['score']:
                changes.append({'member':row['member'],'before':before.get(row['member']),'after':row['score']})
    return {'schema':1,'operation':plan['operation'],'from_generation':plan.get('from_generation'),
            'source_sha256':digest(plan['source_rows']),'target_sha256':digest(rows),'changes':changes}


def checkpoint(path,value):
    if path.is_symlink():raise ValueError('checkpoint symlink')
    temporary=path.with_name('checkpoint.tmp-'+str(os.getpid()))
    try:
