            stream.write(canonical(value)+b'\n');stream.flush();os.fsync(stream.fileno())
        os.replace(temporary,path)
    finally:temporary.unlink(missing_ok=True)


def pages_directory(directory):
    path=directory/'pages'
    if path.is_symlink():raise ValueError('pages directory symlink')
    path.mkdir(exist_ok=True)
    if path.resolve()!=path:raise ValueError('pages escape')
    return path


def read_json(path):
    if path.is_symlink():raise ValueError('artifact symlink')
    return json.loads(path.read_text(encoding='utf-8'))


def validate_pages(directory,state,rows,revision):
    pages=pages_directory(directory);offset=0;chain='0'*64;descriptors=[]
    if (state['revision']!=revision or state['native_sha256']!=digest(rows) or
            type(state['page_size'])is not int or not 1<=state['page_size']<=100 or
            type(state['page_count'])is not int or state['page_count']<0):
        raise ValueError('checkpoint identity')
    for index in range(state['page_count']):
