def csv_bytes(rows):
    stream=io.StringIO(newline='');writer=csv.writer(stream,lineterminator='\n')
    writer.writerow(['member','score'])
    writer.writerows((r['member'],r['score'])for r in rows)
    return stream.getvalue().encode()


