def freeze(command,live,snapshot,revision_key,revision):
    if len({live,snapshot,revision_key})!=3 or not isinstance(revision,str) or not revision:raise ValueError('distinct keys and nonempty revision')
    result=command('EVAL',"if redis.call('EXISTS',KEYS[2])==1 or redis.call('EXISTS',KEYS[3])==1 then return -1 end;redis.call('ZUNIONSTORE',KEYS[2],1,KEYS[1]);redis.call('SET',KEYS[3],ARGV[1]);return redis.call('ZCARD',KEYS[2])",3,live,snapshot,revision_key,revision)
    if result<0:raise ValueError('immutable destination already exists')
    return result
def page(command,snapshot,revision_key,expected,start,count):
    if type(start) is not int or start<0 or type(count) is not int or not 1<=count<=100:raise ValueError('bounded pagination')
    result=command('EVAL',"if redis.call('GET',KEYS[2])~=ARGV[1] then return {-1} end;return {redis.call('ZCARD',KEYS[1]),redis.call('ZREVRANGE',KEYS[1],ARGV[2],tonumber(ARGV[2])+tonumber(ARGV[3])-1,'WITHSCORES')}",2,snapshot,revision_key,expected,start,count)
    if result[0]<0:raise ValueError('revision mismatch')
    raw=result[1];items=[{'member':raw[i],'score':float(raw[i+1])} for i in range(0,len(raw),2)]
    return {'revision':expected,'items':items,'next_offset':start+len(items) if start+len(items)<result[0] else None}
def corrected(command,old,old_revision_key,new,new_revision_key,revision,member,score):
    if len({old,old_revision_key,new,new_revision_key})!=4 or not isinstance(revision,str) or not revision or not isinstance(member,str) or not member or type(score) is not int or abs(score)>2**53-1:raise ValueError('immutable revision and integer correction')
    result=command('EVAL',"if redis.call('EXISTS',KEYS[2])==0 or redis.call('EXISTS',KEYS[3])==1 or redis.call('EXISTS',KEYS[4])==1 then return -1 end;redis.call('ZUNIONSTORE',KEYS[3],1,KEYS[1]);redis.call('ZADD',KEYS[3],ARGV[3],ARGV[2]);redis.call('SET',KEYS[4],ARGV[1]);return redis.call('ZCARD',KEYS[3])",4,old,old_revision_key,new,new_revision_key,revision,member,score)
    if result<0:raise ValueError('source missing or destination occupied')
